CREATE OR REPLACE FUNCTION public.save_scoped_lunch(_scope text,_barber uuid,_start time,_end time) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Acesso restrito.' USING ERRCODE='42501'; END IF; IF _scope NOT IN ('shop','team','barber') OR (_scope='barber' AND NOT EXISTS(SELECT 1 FROM public.barbers WHERE id=_barber AND archived_at IS NULL)) THEN RAISE EXCEPTION 'Selecione o barbeiro.'; END IF; IF _start='00:00'::time AND _end='00:00'::time THEN _start:=NULL; _end:=NULL; END IF; IF (_start IS NULL)<>(_end IS NULL) OR _end<=_start THEN RAISE EXCEPTION 'Informe início e fim válidos.'; END IF; IF _scope='shop' THEN UPDATE public.operation_settings SET lunch_start=_start,lunch_end=_end WHERE id=1; ELSE INSERT INTO public.barber_lunch_overrides SELECT id,_start,_end FROM public.barbers WHERE archived_at IS NULL AND (_scope='team' OR id=_barber) ON CONFLICT(barber_id) DO UPDATE SET starts_time=excluded.starts_time,ends_time=excluded.ends_time; UPDATE public.barbers SET lunch_start=NULL WHERE archived_at IS NULL AND (_scope='team' OR id=_barber); END IF; END $$;
CREATE OR REPLACE FUNCTION public.get_barber_absences_public() RETURNS TABLE(barber_id uuid,starts_on date,ends_on date,is_vacation boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT a.barber_id,a.starts_on,a.ends_on,a.kind='ferias' FROM public.barber_absences a WHERE a.starts_time IS NULL AND a.ends_on>=(now() AT TIME ZONE 'America/Sao_Paulo')::date UNION ALL SELECT b.id,d::date,d::date,a.kind='ferias' FROM public.schedule_absences a JOIN public.barbers b ON a.scope IN ('shop','team') OR a.barber_id=b.id CROSS JOIN LATERAL generate_series(greatest(a.starts_on,(now() AT TIME ZONE 'America/Sao_Paulo')::date)::timestamp,a.ends_on::timestamp,interval '1 day') d WHERE a.starts_time IS NULL AND public.schedule_absence_matches(a.starts_on,a.ends_on,a.weekdays,d::date) $$;
CREATE OR REPLACE FUNCTION public.block_shop_closed_date() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status<>'cancelado' AND (EXISTS(SELECT 1 FROM public.shop_blocked_dates WHERE day=(NEW.starts_at AT TIME ZONE 'America/Sao_Paulo')::date) OR EXISTS(SELECT 1 FROM public.schedule_absences x WHERE x.scope='shop' AND public.schedule_absence_matches(x.starts_on,x.ends_on,x.weekdays,(NEW.starts_at AT TIME ZONE 'America/Sao_Paulo')::date) AND (x.starts_time IS NULL OR ((NEW.starts_at AT TIME ZONE 'America/Sao_Paulo')::time<x.ends_time AND (NEW.ends_at AT TIME ZONE 'America/Sao_Paulo')::time>x.starts_time)))) THEN RAISE EXCEPTION 'Barbearia fechada neste período.'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.guard_schedule_absence() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN NEW.created_by:=OLD.created_by; NEW.created_at:=OLD.created_at; END IF; IF auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(),'admin') AND NEW.created_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Acesso restrito.' USING ERRCODE='42501'; END IF; RETURN NEW; END $$;
CREATE TRIGGER schedule_absences_guard BEFORE INSERT OR UPDATE ON public.schedule_absences FOR EACH ROW EXECUTE FUNCTION public.guard_schedule_absence();